  "jungle.howTo.1": "Du bist im Dschungel gestrandet — triff Entscheidungen für dein Überleben",
  "jungle.howTo.2": "Jede Entscheidung beeinflusst deine KP und deinen Score unterschiedlich",
  "jungle.howTo.3": "Wenn deine KP 0 erreichen, ist das Spiel vorbei",
  "jungle.howTo.4": "Überlebe alle 8 Szenarien, um zu gewinnen!",
  "jungle.scene6": "Du findest einen verletzten Vogel. Was tust du?",
  "jungle.s6c1": "Trage ihn vorsichtig — er könnte dich zu einem Pfad führen (+5 KP, +25 Punkte)",
  "jungle.s6c2": "Lass ihn — sich um ihn zu kümmern kostet Energie (0 KP, +10 Punkte)",
  "jungle.scene7": "Ein Fluss versperrt dir den Weg. Das Wasser sieht schnell aus.",
  "jungle.s7c1": "Baue ein Floß aus umgestürzten Baumstämmen (−5 KP, +40 Punkte)",
  "jungle.s7c2": "Geh flussaufwärts, um eine flache Stelle zu finden (+10 KP, +20 Punkte)",
  "jungle.scene8": "Du siehst in der Ferne Rauch.",
  "jungle.s8c1": "Geh in Richtung Rauch — vielleicht ist es eine Rettung! (+15 KP, +45 Punkte)",
  "jungle.s8c2": "Meide ihn — könnte ein Busch-/Waldbrand sein (−5 KP, +15 Punkte)",
  "jungle.scene9": "Die Nacht bricht herein. Du brauchst Schutz.",
  "jungle.s9c1": "Steig auf einen hohen Baum, um dich vor Raubtieren zu schützen (+10 KP, +30 Punkte)",
  "jungle.s9c2": "Baue einen Unterstand am Boden mit Ästen (−5 KP, +35 Punkte)",
  "jungle.scene10": "Du findest eine Frucht, die du nicht kennst. Du bist sehr hungrig.",
  "jungle.s10c1": "Iss sie — du verhungerst! (−20 KP, +30 Punkte)",
  "jungle.s10c2": "Testiere zuerst ein kleines Stück auf deiner Haut (0 KP, +20 Punkte)",
  "jungle.scene11": "Auf dem Pfad windet sich eine große Schlange.",
  "jungle.s11c1": "Geh langsam zurück und finde eine Umleitung (+5 KP, +30 Punkte)",
  "jungle.s11c2": "Versuche, sie zu verscheuchen (−25 KP, +40 Punkte)",
  "jungle.scene12": "Du hörst einen Wasserfall — deine Wasservorräte sind kritisch niedrig.",
  "jungle.s12c1": "Folge dem Geräusch, um frisches Wasser zu finden (+20 KP, +35 Punkte)",
  "jungle.s12c2": "Ignoriere es und geh weiter (−15 KP, +20 Punkte)",
  "jungle.scene13": "Ein Sturm nähert sich rasch.",
  "jungle.s13c1": "Finde höheres Gelände und Schutz (+10 KP, +25 Punkte)",
  "jungle.s13c2": "Bewege dich weiter, um zu entkommen (−10 KP, +30 Punkte)",
  "jungle.scene14": "Du findest eine Höhle. Es wird dunkel.",
  "jungle.s14c1": "Geh in die Höhle für Schutz (+15 KP, +30 Punkte)",
  "jungle.s14c2": "Schlaf unter einem Baum — die Höhle könnte besetzt sein (+5 KP, +20 Punkte)",
  "jungle.scene15": "Du bist erschöpft. Vor dir sieht es nach einer sicheren Lichtung aus.",
  "jungle.s15c1": "Ruh dich aus und erhol dich (+20 KP, +20 Punkte)",
  "jungle.s15c2": "Mach weiter — hier ist Ruhe gefährlich (−5 KP, +30 Punkte)",
  "jungle.scene16": "Du findest eine alte Karte, in einen Baum geritzt.",
  "jungle.s16c1": "Folge der Richtung auf der Karte (+5 KP, +40 Punkte)",
  "jungle.s16c2": "Ignoriere sie — sie könnte veraltet sein (0 KP, +10 Punkte)",
  "jungle.scene17": "Wildschweine überqueren deinen Weg und gehen aggressiv vor.",
  "jungle.s17c1": "Steig sofort in den nächstgelegenen Baum (+5 KP, +30 Punkte)",
  "jungle.s17c2": "Bleib stehen und schrei (−20 KP, +35 Punkte)",
  "jungle.scene18": "Du findest ein verlassenes Lager mit Vorräten.",
  "jungle.s18c1": "Nimm alles Nützliche (+20 KP, +50 Punkte)",
  "jungle.s18c2": "Lass es — vielleicht braucht es später jemand (0 HP, +10 Punkte)",
  "jungle.scene19": "Ein Affe stiehlt deine Brottasche!",
  "jungle.s19c1": "Jage den Affen (−10 HP, +40 Punkte)",
  "jungle.s19c2": "Lass es — lohnt sich nicht, um Energie zu verschwenden (+0 HP, +15 Punkte)",
  "jungle.scene20": "Du hörst einen Hubschrauber über dir.",
  "jungle.s20c1": "Sofort ein Signalfeuer entzünden! (+30 HP, +60 Punkte)",
  "jungle.s20c2": "Winke mit den Armen — vielleicht sieht es dich (+5 HP, +40 Punkte)",
