  "legal.privacy.collect.messaging.heading": "Nachrichten über Facebook Messenger und Instagram Direct",
  "legal.privacy.collect.messaging.text": "Wenn Sie einer Visionex-Seite oder einem Visionex-Konto über Facebook Messenger oder Instagram Direct schreiben, übermittelt Meta uns den von Ihnen verfassten Text, seine eigene eingeschränkte Kennung für Sie (eine seiten- oder Instagram-bezogene ID, nicht Ihr Profil, Ihre E-Mail-Adresse oder Ihre Telefonnummer), die Nachrichtenkennung und den Sendezeitpunkt. Wir speichern dies, um Ihre Frage zu lesen, den Gesprächsverlauf zu ordnen, dieselbe Nachricht nicht zweimal zu beantworten und den Vorgang an einen Menschen zu übergeben, wenn automatisierte Hilfe nicht ausreicht. Der Text Ihrer Nachricht wird von externen KI-Anbietern verarbeitet, um eine Antwort zu erzeugen. Ihr Facebook- oder Instagram-Passwort, Ihre Freundes- oder Follower-Liste und Ihre Profilangaben erhalten wir zu keinem Zeitpunkt.",
  "legal.privacy.third.meta.name": "Meta Platforms (Facebook Messenger, Instagram Direct, WhatsApp)",
  "legal.privacy.third.meta.purpose": "Stellt die Nachrichten zu, die Sie über Messenger, Instagram Direct oder WhatsApp an Visionex senden, und übermittelt Ihnen unsere Antworten zurück. Meta verarbeitet diese Nachrichten auf seinen eigenen Plattformen nach seinen eigenen Bedingungen und seiner Datenschutzerklärung.",
  "legal.privacy.deletionLink": "Um die Löschung von Daten zu verlangen, die wir über Facebook Messenger oder Instagram Direct erhalten haben, folgen Sie der Anleitung unter",
  "legal.dataDeletion.title": "Antrag auf Datenlöschung",
  "legal.dataDeletion.intro": "Diese Seite erklärt, wie Sie die Löschung der Daten verlangen, die Visionex über Sie speichert — einschließlich der Daten, die wir von Meta erhalten haben, als Sie uns über Facebook Messenger oder Instagram Direct geschrieben haben.",
  "legal.dataDeletion.howTitle": "So beantragen Sie die Löschung",
  "legal.dataDeletion.step1": "Senden Sie uns eine E-Mail mit dem Betreff „Antrag auf Datenlöschung“.",
  "legal.dataDeletion.step2": "Teilen Sie uns mit, auf welchen Dienst sich die Daten beziehen — etwa eine Nachricht, die Sie über Facebook Messenger oder Instagram Direct an die Visionex-Seite gesendet haben — und ungefähr wann Sie uns kontaktiert haben, damit wir die richtige Konversation finden. Wenn Sie ein Visionex-Konto haben, senden Sie den Antrag bitte von der dort hinterlegten E-Mail-Adresse.",
  "legal.dataDeletion.step3": "Wir bestätigen den Eingang des Antrags, löschen die vorhandenen Daten und teilen Ihnen anschließend schriftlich mit, was entfernt wurde.",
  "legal.dataDeletion.contact": "Anträge richten Sie an",
  "legal.dataDeletion.whatTitle": "Was gelöscht wird",
  "legal.dataDeletion.whatBody": "Für Facebook Messenger und Instagram Direct löschen wir den bei uns gespeicherten Gesprächsverlauf: den von Ihnen gesendeten Text, unsere Antworten, die eingeschränkte Kennung, die Meta uns zu Ihnen übermittelt hat, die Nachrichtenkennungen und die Zeitstempel. Bei einem Visionex-Konto löschen oder anonymisieren wir die dort gespeicherten personenbezogenen Daten. Was Meta auf seinen eigenen Plattformen speichert, können wir nicht löschen: Die Kopie der Konversation in Ihrem Messenger- oder Instagram-Postfach gehört zu Ihrem Meta-Konto und lässt sich dort von Ihnen selbst entfernen.",
  "legal.dataDeletion.timingTitle": "Wie lange es dauert",
  "legal.dataDeletion.timingBody": "Wir bemühen uns, die Löschung innerhalb von 30 Tagen nach Bestätigung Ihres Antrags abzuschließen. Soweit wir zur Aufbewahrung eines begrenzten Datensatzes verpflichtet sind — aus Gründen der Sicherheit, der Betrugsprävention, der Streitbeilegung oder einer gesetzlichen Pflicht — bewahren wir nur das dafür Erforderliche auf und löschen den Rest.",
  "legal.dataDeletion.accountTitle": "Ein Visionex-Konto löschen",
  "legal.dataDeletion.accountBody": "Wenn Sie ein Visionex-Konto haben, können Sie uns über dieselbe Adresse auch bitten, es vollständig zu schließen. Mit der Schließung werden die dort gespeicherten personenbezogenen Daten gelöscht oder anonymisiert, vorbehaltlich der oben beschriebenen begrenzten Aufbewahrung.",
  "legal.dataDeletion.footer": "Ausführliche Angaben dazu, welche Daten wir erheben und warum, finden Sie in der",
